  "claims": [
    {
      "claim": "Morphine, the closest supplied morphinan analog, had a mean absolute oral bioavailability of 29.2 ± 7.2% after a fasted oral tablet versus IV in healthy volunteers, above the 20% threshold.",
      "card_ids": ["C08","C10"]
    },
    {
      "claim": "Ethylmorphine showed absolute oral bioavailability of 28% in a subject receiving both oral and IV doses, and a median systemic availability of 0.74 by metabolite recovery.",
      "card_ids": ["C06","C03"]
    },
    {
      "claim": "Codeine sulfate had oral bioavailability of 80.5% in healthy subjects; relative bioavailability estimates versus intramuscular dosing were 50.2 ± 2.1% and 54.8 ± 4.9%.",
      "card_ids": ["C07","C19","C25","C39","C49"]
    },
    {
      "claim": "Morphine after oral extended-release or immediate-release diacetylmorphine in fasted subjects had absolute bioavailability of 53–61% (deconvolution estimates 0.55–0.57), all above the 20% threshold.",
      "card_ids": ["C28","C29","C35","C47","C51"]
    },
    {
      "claim": "The L3 naltrexone oral Cmax record demonstrates measurable oral exposure but lacks an IV comparator or F value, so it does not provide affirmative threshold-relevant evidence for the query.",
      "card_ids": ["C59"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "weakened",
      "card_ids": ["C59","C73"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule is present in the supplied records.",
    "The L3 naltrexone Cmax record has no IV comparator, so it cannot be converted into an F estimate.",
    "The query differs from the high-F morphinan analogs at N-substitution, C6 oxidation state, and 14-hydroxylation; the quantitative impact on first-pass metabolism is not addressed by any card.",
    "No query-specific metabolism, clearance, or efflux data are available at this level."
  ],
  "decision_summary": "Prediction remains high because all supplied morphinan analog F measurements (morphine ~29%, ethylmorphine 28–74%, codeine 50–80%) are above the 20% threshold, and L3 adds no affirmative threshold-relevant evidence for F < 20%. However, L3 introduces naltrexone as a closer structural analog but only with oral Cmax (no F), and the structural differences from morphine increase uncertainty; confidence is therefore lowered to low."
}

